export function warrantyLabel(language:UiLanguage,english:string):string {
  return uiText(language,english,bangla[english]??english);
}

/** Label/value separation keeps filters and posting transitions language independent. */
export function warrantyOptions(language:UiLanguage,values:readonly string[]) {
  return values.map(value=>({value,label:warrantyLabel(language,value)}));
}
